    45→pub fn get_custody_groups(
    46→    raw_node_id: [u8; 32],
    47→    custody_group_count: u64,
    48→    config: &Config,
    49→) -> Result<HashSet<CustodyIndex>> {
    50→    let number_of_custody_groups = config.number_of_custody_groups;
    51→    ensure!(
    52→        custody_group_count <= number_of_custody_groups,
    53→        Error::InvalidCustodyGroupCount {
    54→            custody_group_count,
    55→            number_of_custody_groups,
    56→        },
    57→    );
    58→
    59→    // Skip computation for super node
    60→    if custody_group_count == number_of_custody_groups {
    61→        return Ok((0..number_of_custody_groups).collect::<HashSet<_>>());
    62→    }
    63→
    64→    let mut current_id = NodeId::from_be_bytes(raw_node_id);
    65→
    66→    let mut custody_groups = BTreeSet::new();
    67→    while (custody_groups.len() as u64) < custody_group_count {
    68→        let mut hasher = Sha256::new();
    69→        let mut bytes = [0u8; 32];
    70→
    71→        current_id.into_raw().to_little_endian(&mut bytes);
    72→
    73→        hasher.update(bytes);
    74→        bytes = hasher.finalize().into();
    75→
    76→        let output_prefix = [
    77→            bytes[0], bytes[1], bytes[2], bytes[3], bytes[4], bytes[5], bytes[6], bytes[7],
    78→        ];
    79→
    80→        let output_prefix_u64 = u64::from_le_bytes(output_prefix);
    81→        let custody_group = output_prefix_u64
    82→            .checked_rem(number_of_custody_groups)
    83→            .expect("number of custody groups must not be zero");
    84→        custody_groups.insert(custody_group);
    85→
    86→        if current_id == Uint256::MAX {
    87→            // > Overflow prevention
    88→            current_id = Uint256::ZERO;
    89→        } else {
    90→            current_id = current_id + Uint256::one();
    91→        }
    92→    }
    93→
    94→    Ok(custody_groups.into_iter().collect())
    95→}
