   260→        cells_and_kzg_proofs.len() == blob_count,
   261→        Error::BlobCommitmentsLengthMismatch {
   262→            blob_count,
   263→            commitments_length: kzg_commitments.len(),
   264→        }
   265→    );
   266→
   267→    let mut sidecars = vec![];
   268→    for column_index in 0..P::NumberOfColumns::USIZE {
   269→        let column = ContiguousList::try_from_iter(
   270→            (0..blob_count)
   271→                .map(|row_index| cells_and_kzg_proofs[row_index].0[column_index].clone()),
   272→        )?;
   273→        let kzg_proofs = ContiguousList::try_from_iter(
   274→            (0..blob_count).map(|row_index| cells_and_kzg_proofs[row_index].1[column_index]),
   275→        )?;
   276→
   277→        sidecars.push(
   278→            DataColumnSidecar {
   279→                index: ColumnIndex::try_from(column_index)?,
   280→                column,
   281→                kzg_commitments: kzg_commitments.clone(),
   282→                kzg_proofs,
   283→                signed_block_header,
   284→                kzg_commitments_inclusion_proof,
   285→            }
   286→            .into(),
   287→        );
   288→    }
   289→
   290→    Ok(sidecars)
   291→}
   292→
   293→pub fn construct_data_column_sidecars<P: Preset>(
   294→    signed_block: &SignedBeaconBlock<P>,
   295→    cells_and_kzg_proofs: &[CellsAndKzgProofs<P>],
   296→) -> Result<Vec<Arc<DataColumnSidecar<P>>>> {
   297→    let signed_block_header = signed_block.to_header();
   298→    let Some(post_electra_beacon_block_body) = signed_block.message().body().post_electra() else {
   299→        return Ok(vec![]);
   300→    };
   301→
   302→    let kzg_commitments = post_electra_beacon_block_body.blob_kzg_commitments();
   303→    if kzg_commitments.is_empty() {
   304→        return Ok(vec![]);
   305→    }
   306→
   307→    let kzg_commitments_inclusion_proof =
   308→        misc::kzg_commitments_inclusion_proof(post_electra_beacon_block_body);
   309→
   310→    get_data_column_sidecars(
