use std::{collections::HashSet, sync::Arc};

use anyhow::Result;
use dashmap::DashMap;
use eth2_libp2p::PeerId;
use execution_engine::{
    BlobAndProofV1, BlobAndProofV2, BlockOrDataColumnSidecar, EngineGetBlobsParams,
    EngineGetBlobsV1Params, EngineGetBlobsV2Params,
};
use fork_choice_control::Wait;
use futures::{
    channel::mpsc::{UnboundedReceiver, UnboundedSender},
    StreamExt as _,
};
use helper_functions::misc;
use log::{debug, warn};
use prometheus_metrics::Metrics;
use ssz::ContiguousList;
use std_ext::ArcExt as _;
use types::{
    combined::SignedBeaconBlock,
    deneb::{containers::BlobIdentifier, primitives::BlobIndex},
    fulu::{
        containers::{DataColumnIdentifier, DataColumnsByRootIdentifier},
        primitives::ColumnIndex,
    },
    phase0::primitives::Slot,
    preset::Preset,
    traits::SignedBeaconBlock as _,
};

use crate::{
    messages::{BlobFetcherToP2p, Eth1ApiToBlobFetcher},
    ApiController, Eth1Api,
};

pub struct ExecutionBlobFetcher<P: Preset, W: Wait> {
    api: Arc<Eth1Api>,
    controller: ApiController<P, W>,
    received_blob_sidecars: Arc<DashMap<BlobIdentifier, Slot>>,
    received_data_column_sidecars: Arc<DashMap<DataColumnIdentifier, Slot>>,
    metrics: Option<Arc<Metrics>>,
    p2p_tx: UnboundedSender<BlobFetcherToP2p<P>>,
    rx: UnboundedReceiver<Eth1ApiToBlobFetcher<P>>,
}

impl<P: Preset, W: Wait> ExecutionBlobFetcher<P, W> {
    pub const fn new(
        api: Arc<Eth1Api>,
        controller: ApiController<P, W>,
        received_blob_sidecars: Arc<DashMap<BlobIdentifier, Slot>>,
        received_data_column_sidecars: Arc<DashMap<DataColumnIdentifier, Slot>>,
        metrics: Option<Arc<Metrics>>,
        p2p_tx: UnboundedSender<BlobFetcherToP2p<P>>,
        rx: UnboundedReceiver<Eth1ApiToBlobFetcher<P>>,
    ) -> Self {
        Self {
            api,
            controller,
            received_blob_sidecars,
            received_data_column_sidecars,
            metrics,
            p2p_tx,
            rx,
        }
    }

    pub async fn run(mut self) -> Result<()> {
        while let Some(message) = self.rx.next().await {
            match message {
                Eth1ApiToBlobFetcher::GetBlobs(params) => match params {
                    EngineGetBlobsParams::V1(EngineGetBlobsV1Params {
                        block,
                        blob_identifiers,
                        peer_id,
                    }) => self.get_blobs_v1(block, blob_identifiers, peer_id).await,
                    EngineGetBlobsParams::V2(EngineGetBlobsV2Params {
                        block_or_sidecar,
                        data_column_identifiers,
                    }) => {
                        self.get_blobs_v2(block_or_sidecar, data_column_identifiers)
                            .await
                    }
                },
                Eth1ApiToBlobFetcher::Stop => break,
            }
        }

        Ok(())
    }

    async fn get_blobs_v1(
        &self,
        block: Arc<SignedBeaconBlock<P>>,
        blob_identifiers: Vec<BlobIdentifier>,
        peer_id: Option<PeerId>,
    ) {
        let slot = block.message().slot();
        let block_root = block.message().hash_tree_root();

        if self.controller.contains_block(block_root) {
            debug!("cannot fetch blobs from EL: block has been imported");
            return;
        }

        if let Some(body) = block.message().body().post_deneb() {
            let missing_blob_indices = blob_identifiers
                .iter()
                .filter(|identifier| !self.received_blob_sidecars.contains_key(identifier))
                .map(|identifier| identifier.index)
                .collect::<HashSet<BlobIndex>>();

            let kzg_commitments = body
                .blob_kzg_commitments()
                .iter()
                .zip(0..)
                .filter(|(_, index)| missing_blob_indices.contains(index))
                .collect::<Vec<_>>();

            if kzg_commitments.is_empty() {
                debug!(
                    "cannot fetch blobs from EL: all requested blob sidecars have been received"
                );
                return;
            }

            if self.controller.is_forward_synced()
                && !self.controller.store_config().disable_engine_getblobs
            {
                let versioned_hashes = kzg_commitments
                    .iter()
                    .copied()
                    .map(|(commitment, _)| misc::kzg_commitment_to_versioned_hash(*commitment))
                    .collect();

                let mut blob_sidecars = vec![];

                match self.api.get_blobs_v1::<P>(versioned_hashes).await {
                    Ok(blobs_and_proofs) => {
                        let block_header = block.to_header();

                        for (blob_and_proof, kzg_commitment, index) in blobs_and_proofs
                            .into_iter()
                            .zip(kzg_commitments.into_iter())
                            .filter_map(|(blob_and_proof, (kzg_commitment, index))| {
                                blob_and_proof
                                    .map(|blob_and_proof| (blob_and_proof, kzg_commitment, index))
                            })
                        {
                            let BlobAndProofV1 { blob, proof } = blob_and_proof;
                            let blob_identifier = BlobIdentifier { block_root, index };

                            if self.received_blob_sidecars.contains_key(&blob_identifier) {
                                debug!(
                                    "received blob from EL is already known: {blob_identifier:?}, \
                                     slot: {slot}"
                                );
                            } else {
                                match misc::construct_blob_sidecar(
                                    &block,
                                    block_header,
                                    index,
                                    blob,
                                    *kzg_commitment,
                                    proof,
                                ) {
                                    Ok(blob_sidecar) => {
                                        debug!(
                                            "received blob sidecar from EL: {blob_identifier:?}, \
                                             slot: {slot}"
                                        );

                                        // Record all blob_sidecars as received first and push to controller
                                        // on a second pass to avoid spawning extra `engine_getBlobs` calls.
                                        self.received_blob_sidecars.insert(blob_identifier, slot);
                                        blob_sidecars.push(Arc::new(blob_sidecar));
                                    }
                                    Err(error) => warn!(
                                        "failed to construct blob sidecar with blob and proof \
                                         received from execution layer: {error:?}"
                                    ),
                                }
                            }
                        }
                    }
                    Err(error) => warn!("engine_getBlobsV1 call failed: {error}"),
                }

                for blob_sidecar in blob_sidecars {
                    self.controller.on_el_blob_sidecar(blob_sidecar);
                }
            }

            // Request remaining missing blob sidecars from P2P
            let missing_blob_identifiers = missing_blob_indices
                .into_iter()
                .filter_map(|index| {
                    let identifier = BlobIdentifier { block_root, index };
                    (!self.received_blob_sidecars.contains_key(&identifier)).then_some(identifier)
                })
                .collect::<Vec<_>>();

            debug!("missing blob sidecars after EL: {missing_blob_identifiers:?}");

            if !missing_blob_identifiers.is_empty() {
                BlobFetcherToP2p::BlobsNeeded(missing_blob_identifiers, slot, peer_id)
                    .send(&self.p2p_tx);
            }
        }
    }

    #[expect(clippy::too_many_lines)]
    async fn get_blobs_v2(
        &self,
        block_or_sidecar: BlockOrDataColumnSidecar<P>,
        data_column_identifiers: Vec<DataColumnIdentifier>,
    ) {
        let slot = block_or_sidecar.slot();
        let block_root = block_or_sidecar.block_root();

        if self.controller.contains_block(block_root)
            || self
                .controller
                .is_sidecars_construction_started(&block_root)
        {
            debug!("cannot fetch blobs from EL: block has been imported, or is being imported");
            return;
        }

        let Some(kzg_commitments) = block_or_sidecar.kzg_commitments() else {
            return;
        };

        let missing_columns_indices = data_column_identifiers
            .iter()
            .filter(|identifier| !self.received_data_column_sidecars.contains_key(identifier))
            .map(|identifier| identifier.index)
            .collect::<HashSet<ColumnIndex>>();

        if missing_columns_indices.is_empty() {
            debug!(
                "cannot fetch blobs from EL: all missing data column sidecars have been received"
            );
            return;
        }

        if self.controller.is_forward_synced()
            && !self.controller.store_config().disable_engine_getblobs
        {
            let request_timer = self
                .metrics
                .as_ref()
                .map(|metrics| metrics.engine_get_blobs_v2_request_time.start_timer());

            if let Some(metrics) = self.metrics.as_ref() {
                metrics.engine_get_blobs_v2_requests_count.inc();
            }

            let expected_blobs_count = kzg_commitments.len();
            let versioned_hashes = kzg_commitments
                .iter()
                .copied()
                .map(misc::kzg_commitment_to_versioned_hash)
                .collect::<Vec<_>>();

            match self.api.get_blobs_v2::<P>(versioned_hashes).await {
                Ok(blobs_and_proofs_opt) => {
                    prometheus_metrics::stop_and_record(request_timer);

                    if let Some(blobs_and_proofs) = blobs_and_proofs_opt {
                        if blobs_and_proofs.len() == expected_blobs_count {
                            if let Some(metrics) = self.metrics.as_ref() {
                                metrics.engine_get_blobs_v2_responses_count.inc();
                            }

                            let (received_blobs, received_proofs): (Vec<_>, Vec<_>) =
                                blobs_and_proofs
                                    .into_iter()
                                    .map(|BlobAndProofV2 { blob, proofs }| (blob, proofs))
                                    .unzip();

                            debug!(
                                "received all {expected_blobs_count} blob sidecars from EL at slot: {slot}",
                            );

                            let cells_proofs = received_proofs
                                .into_iter()
                                .flat_map(IntoIterator::into_iter)
                                .collect::<Vec<_>>();

                            let timer = self.metrics.as_ref().map(|metrics| {
                                metrics.data_column_sidecar_computation.start_timer()
                            });

                            let controller = self.controller.clone_arc();

                            let received_data_column_sidecars =
                                self.received_data_column_sidecars.clone_arc();

                            let reconstruction_result = tokio::task::spawn_blocking(move || {
                                let mut data_column_sidecars = vec![];

                                match eip_7594::try_convert_to_cells_and_kzg_proofs::<P>(
                                    &received_blobs,
                                    &cells_proofs,
                                    controller.store_config().kzg_backend,
                                ) {
                                    Ok(cells_and_kzg_proofs) => {
                                        let result = match block_or_sidecar {
                                            BlockOrDataColumnSidecar::Block(block) => eip_7594::construct_data_column_sidecars(
                                                &block,
                                                &cells_and_kzg_proofs,
                                            ),
                                            BlockOrDataColumnSidecar::Sidecar(sidecar) => eip_7594::construct_data_column_sidecars_from_sidecar(
                                                &sidecar,
                                                &cells_and_kzg_proofs,
                                            ),
                                        };

                                        prometheus_metrics::stop_and_record(timer);

                                        match result {
                                            Ok(data_columns) => {
                                                controller.mark_sidecar_construction_started(block_root, slot);

                                                for data_column_sidecar in
                                                    data_columns.into_iter().filter(|column| {
                                                        controller
                                                            .sampling_columns()
                                                            .contains(&column.index)
                                                    })
                                                {
                                                    let identifier = DataColumnIdentifier {
                                                        block_root,
                                                        index: data_column_sidecar.index,
                                                    };

                                                    received_data_column_sidecars.insert(identifier, slot);
                                                    data_column_sidecars.push(data_column_sidecar);
                                                }
                                            }
                                            Err(error) => {
                                                controller.mark_sidecar_construction_failed(&block_root);

                                                warn!(
                                                    "failed to construct data column sidecars with \
                                                    cells and kzg proofs: {error:?}"
                                                );
                                            }
                                        }
                                    }
                                    Err(error) => warn!(
                                        "failed to convert blobs received from EL into extended cells: {error:?}"
                                    ),
                                }

                                data_column_sidecars
                            }).await;

                            match reconstruction_result {
                                Ok(data_column_sidecars) => {
                                    for data_column_sidecar in data_column_sidecars {
                                        self.controller
                                            .on_el_data_column_sidecar(data_column_sidecar);
                                    }
                                }
                                Err(error) => {
                                    warn!("failed to reconstruct data columns from EL response: {error:?}")
                                }
                            }
                        } else {
                            warn!(
                                "EL must response all blobs or null (expected: {}, got: {})",
                                expected_blobs_count,
                                blobs_and_proofs.len(),
                            );
                        }
                    } else {
                        debug!("EL doesn't has all blobs to response back",);
                    }
                }
                Err(error) => warn!("engine_getBlobsV2 call failed: {error}"),
            }
        }

        if !self
            .controller
            .is_sidecars_construction_started(&block_root)
        {
            // Request remaining missing data column sidecars from P2P
            let missing_indices = missing_columns_indices
                .into_iter()
                .filter(|index| {
                    !self
                        .received_data_column_sidecars
                        .contains_key(&DataColumnIdentifier {
                            block_root,
                            index: *index,
                        })
                })
                .collect::<Vec<_>>();

            debug!("missing data columns sidecars: {missing_indices:?} at block {block_root}");

            if !missing_indices.is_empty() {
                let columns = ContiguousList::try_from(missing_indices)
                    .expect("missing column indices must not be more than NUMBER_OF_COLUMNS");

                BlobFetcherToP2p::DataColumnsNeeded(
                    DataColumnsByRootIdentifier {
                        block_root,
                        columns,
                    },
                    slot,
                )
                .send(&self.p2p_tx);
            }
        }
    }
}

// `Mutator::run` is executed in a background thread and performs all mutations on a uniquely owned
// copy of `Store` as an alternative to locking.
//
// Some of the earlier designs used `RwLock`s, but they caused all sorts of trouble. Switching from
// a read lock to a write lock must be done carefully to not introduce deadlocks or race conditions.
// `parking_lot` implements upgradable `RwLock`s, but they deadlock when 2 threads try to upgrade
// simultaneously (the other option would be to make one of them successfully lock, but no one seems
// to have proposed that).
//
// There is a number of alternate designs possible. This is just the first one that worked and
// fulfilled our requirements (see the comment in the `controller` module).
//
// The mutator's workload could be reduced by moving the handling of ignored and rejected objects to
// tasks as well, but that would complicate code and would most likely not improve performance much
// (in fact, the opposite may be true because `p2p_tx` would have to be cloned for each task).

use std::{
    collections::{BTreeMap, HashMap, HashSet},
    sync::{
        mpsc::{Receiver, Sender},
        Arc,
    },
    thread::Builder,
    time::Instant,
};

use anyhow::{anyhow, Error as AnyhowError, Result};
use arc_swap::ArcSwap;
use clock::{Tick, TickKind};
use drain_filter_polyfill::VecExt as _;
use eth2_libp2p::GossipId;
use execution_engine::{
    EngineGetBlobsParams, EngineGetBlobsV1Params, EngineGetBlobsV2Params, ExecutionEngine,
    PayloadStatusV1,
};
use fork_choice_store::{
    AggregateAndProofAction, ApplyBlockChanges, ApplyTickChanges, AttestationAction,
    AttestationItem, AttestationOrigin, AttestationValidationError, AttesterSlashingOrigin,
    BlobSidecarAction, BlobSidecarOrigin, BlockAction, BlockOrigin, ChainLink,
    DataColumnSidecarAction, DataColumnSidecarOrigin, Error, PayloadAction, StateCacheProcessor,
    Store, ValidAttestation,
};
use futures::channel::{mpsc::Sender as MultiSender, oneshot::Sender as OneshotSender};
use helper_functions::{accessors, misc, predicates, verifier::NullVerifier};
use itertools::{Either, Itertools as _};
use log::{debug, error, info, trace, warn};
use num_traits::identities::Zero as _;
use prometheus_metrics::Metrics;
use pubkey_cache::PubkeyCache;
use ssz::SszHash as _;
use std_ext::ArcExt as _;
use typenum::Unsigned as _;
use types::{
    combined::{BeaconState, ExecutionPayloadParams, SignedBeaconBlock},
    deneb::containers::{BlobIdentifier, BlobSidecar},
    fulu::{
        containers::{DataColumnIdentifier, DataColumnSidecar, MatrixEntry},
        primitives::ColumnIndex,
    },
    nonstandard::{PayloadStatus, RelativeEpoch, ValidationOutcome},
    phase0::{
        containers::Checkpoint,
        primitives::{ExecutionBlockHash, Slot, ValidatorIndex, H256},
    },
    preset::Preset,
    traits::{BeaconState as _, SignedBeaconBlock as _},
};

use crate::{
    block_processor::BlockProcessor,
    events::{DependentRootsBundle, EventChannels},
    messages::{
        AttestationVerifierMessage, MutatorMessage, P2pMessage, PoolMessage, SubnetMessage,
        SyncMessage, ValidatorMessage,
    },
    misc::{
        BlockBlobAvailability, BlockDataColumnAvailability, Delayed, MutatorRejectionReason,
        PendingAggregateAndProof, PendingAttestation, PendingBlobSidecar, PendingBlock,
        PendingChainLink, PendingDataColumnSidecar, ProcessingTimings, ReorgSource,
        VerifyAggregateAndProofResult, VerifyAttestationResult, WaitingForCheckpointState,
    },
    storage::Storage,
    tasks::{
        AttestationTask, BlobSidecarTask, BlockAttestationsTask, BlockTask, CheckpointStateTask,
        DataColumnSidecarTask, PersistBlobSidecarsTask, PersistDataColumnSidecarsTask,
        PersistPubkeyCacheTask, PreprocessStateTask, RetryDataColumnSidecarTask,
    },
    thread_pool::{Spawn, ThreadPool},
    unbounded_sink::UnboundedSink,
    wait::Wait,
};

const DATA_COLUMN_RETAIN_DURATION_IN_SLOTS: Slot = 2;

#[expect(clippy::struct_field_names)]
pub struct Mutator<P: Preset, E, W, TS, PS, LS, NS, SS, VS> {
    pubkey_cache: Arc<PubkeyCache>,
    store: Arc<Store<P, Storage<P>>>,
    store_snapshot: Arc<ArcSwap<Store<P, Storage<P>>>>,
    state_cache: Arc<StateCacheProcessor<P>>,
    block_processor: Arc<BlockProcessor<P>>,
    event_channels: Arc<EventChannels<P>>,
    execution_engine: E,
    delayed_until_blobs: HashMap<H256, PendingBlock<P>>,
    delayed_until_block: HashMap<H256, Delayed<P>>,
    // We previously ignored objects that would have to be delayed more than one slot. This was
    // based on the assumption that one slot is enough to account for clock differences between
    // nodes. However, this meant that if the application lagged enough to miss multiple slot
    // updates (not necessarily by its own fault), the fork choice store would start ignoring blocks
    // and make the application stop syncing.
    delayed_until_slot: BTreeMap<Slot, Delayed<P>>,
    // `Mutator.delayed_until_payload` is needed mainly to run optimistic sync test cases, but the
    // problem it solves can occur in normal operation as well. The execution layer may finish
    // validating the payload before the fork choice store processes the block containing it.
    delayed_until_payload: HashMap<ExecutionBlockHash, Vec<(PayloadStatusV1, Slot)>>,
    delayed_until_state: HashMap<(H256, Slot), Delayed<P>>,
    // The specification doesn't explicitly state it, but `Store.checkpoint_states` is effectively a
    // cache, as its contents can be recomputed at any time using data from other fields.
    //
    // Advancing a `BeaconState` through slots for each attestation independently results in a
    // massive slowdown. A naive implementation (one that matches `consensus-specs` exactly) could
    // avoid this by processing attestations sequentially and mutating `Store.checkpoint_states`
    // after each one. We cannot do this because we want to process attestations in parallel.
    // We previously solved this for attestations in blocks by extracting their targets and lazily
    // computing the checkpoint state for each target. Individual attestations received in quick
    // succession would still perform slot processing independently.
    waiting_for_checkpoint_states: HashMap<Checkpoint, WaitingForCheckpointState<P>>,
    storage: Arc<Storage<P>>,
    thread_pool: ThreadPool<P, E, W>,
    metrics: Option<Arc<Metrics>>,
    finished_loading_from_storage: bool,
    mutator_tx: Sender<MutatorMessage<P, W>>,
    mutator_rx: Receiver<MutatorMessage<P, W>>,
    attestation_verifier_tx: TS,
    p2p_tx: PS,
    pool_tx: LS,
