                .block_processor
                .validate_block(
                    &self.store,
                    &block,
                    origin.state_root_policy(),
                    origin.data_availability_policy(),
                    &self.execution_engine,
                    NullVerifier,
                )
                .into();

            let block_root = block.message().hash_tree_root();

            self.handle_block(
                wait_group.clone(),
                result,
                origin,
                processing_timings,
                block_root,
            )?;
        }

        self.finished_loading_from_storage = true;

        Ok(())
    }

